          "contact.documentTitle": "Kontakt - Rentulo",
          "contact.eyebrow": "Kontakt",
          "contact.title": "Jak vám můžeme pomoci?",
          "contact.intro": "Máte dotaz k účtu, nabídce, rezervaci nebo fungování Rentula? Napište nám a uveďte co nejpřesněji, s čím potřebujete pomoci.",
          "contact.supportKicker": "Podpora",
          "contact.supportTitle": "Zákaznická podpora",
          "contact.supportText": "Pro otázky k účtu, nabídce, rezervaci nebo technickému problému nás kontaktujte e-mailem.",
          "contact.emailLabel": "E-mail",
