          "contact.toBeAdded": "Bude doplněno",
          "contact.testBadge": "Testovací verze",
          "contact.operatorTitle": "Provozovatel Rentulo",
          "contact.operatorNotice": "Identifikační údaje provozovatele budou doplněny před spuštěním ostrého provozu. Následující položky slouží zatím pouze jako připravená struktura stránky.",
