          "privacy.eyebrow": "Pracovný návrh",
          "privacy.title": "Ochrana osobných údajov",
          "privacy.intro": "Táto stránka opisuje, aké osobné údaje platforma Rentulo pri súčasnom fungovaní spracúva, prečo ich potrebuje a komu ich môže sprístupniť.",
