          "contact.documentTitle": "Contact - Rentulo",
          "contact.eyebrow": "Contact",
          "contact.title": "How can we help?",
          "contact.intro": "Do you have a question about your account, a listing, a reservation or how Rentulo works? Write to us and describe as precisely as possible what you need help with.",
          "contact.supportKicker": "Support",
          "contact.supportTitle": "Customer support",
          "contact.supportText": "For questions about your account, a listing, a reservation or a technical issue, contact us by email.",
          "contact.emailLabel": "Email",
