          "how.back": "← Zurück",
          "how.documentTitle": "So funktioniert es - Rentulo",
          "how.findItem": "Gegenstand finden",
          "how.intro": "Leihe an einem Ort Gegenstände von Menschen in deiner Nähe aus oder biete deine eigenen Gegenstände anderen an.",
          "how.listItem": "Gegenstand anbieten",
          "how.note2Text": "Kontaktdaten und der genaue Abholort sind nicht öffentlich. Sie werden den Beteiligten der Reservierung erst nach der Zahlung angezeigt.",
          "how.note2Title": "Kontaktdaten sind geschützt",
          "how.ownerStep1Text": "Nur angemeldete Benutzer können Angebote hinzufügen.",
          "how.ownerStep1Title": "Anmelden",
