          "contact.documentTitle": "Kontakt - Rentulo",
          "contact.eyebrow": "Kontakt",
          "contact.title": "Jak możemy pomóc?",
          "contact.intro": "Masz pytanie dotyczące konta, oferty, rezerwacji lub działania Rentulo? Napisz do nas i możliwie dokładnie opisz, w czym potrzebujesz pomocy.",
          "contact.supportKicker": "Wsparcie",
          "contact.supportTitle": "Obsługa klienta",
          "contact.supportText": "W sprawach dotyczących konta, oferty, rezerwacji lub problemu technicznego skontaktuj się z nami e-mailem.",
          "contact.emailLabel": "E-mail",
          "contact.phoneLabel": "Telefon",
          "contact.toBeAdded": "Zostanie uzupełnione",
          "contact.testBadge": "Wersja testowa",
          "contact.operatorTitle": "Operator Rentulo",
          "contact.operatorNotice": "Dane identyfikacyjne operatora zostaną uzupełnione przed uruchomieniem produkcyjnym. Poniższe pola służą obecnie wyłącznie jako przygotowana struktura tej strony.",
          "contact.companyLabel": "Nazwa firmy",
          "contact.addressLabel": "Siedziba",
